name = "credentials-backend"
version = "0.1.0"
edition = "2021"
publish = false

[dependencies]
affinidi-did-common = "=0.4.3"
affinidi-encoding = "=0.1.6"
base64 = "=0.23.1"
ed25519-dalek = "=3.0.0"
getrandom = "=0.4.3"
serde = { version = "=1.0.229", features = ["derive"] }
serde_json = "=1.0.151"
sha2 = "=0.11.0"
thiserror = "=2.0.21"
tokio = { version = "=1.53.1", features = ["rt", "time"] }
url = "=2.5.8"

[dev-dependencies]
