//! Issuer and verifier service for membership credentials.
//!
//! - [`issuer`] onboards issuers and signs credentials for their members.
//! - [`verifier`] checks the presentations members show at the door.
//! - [`resolver`] turns a DID into its DID document; [`transport`] fetches
//!   the documents that are hosted rather than encoded in the DID.
//! - [`status`] and [`store`] keep issued credentials and their revocation state.
//! - [`notifier`] tells subscribed relying parties when a status changes;
//!   [`settings`] holds the tenants' subscriptions and [`webhook`] sends the
//!   calls.
//! - [`credential`] is the wire format shared by all of the above.

pub mod credential;
pub mod issuer;
pub mod notifier;
pub mod resolver;
pub mod settings;
pub mod status;
pub mod store;
pub mod transport;
pub mod verifier;
pub mod webhook;
//! DID resolution: from a DID to its DID document.
//!
//! The methods the service has used, oldest first:
//!
//! - `did:key` — the identifier is one multibase-encoded Ed25519 key.
//! - `did:peer:0` — the same, under the peer method.
//! - `did:peer:2` — several keys, each tagged with its purpose, plus service
//!   endpoints, all encoded in the identifier.
//! - `did:web` — the document is published at an HTTPS URL derived from the
//!   identifier and fetched through a [`DocumentTransport`].

use std::sync::Arc;

use affinidi_did_common::Document;
use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use base64::Engine;
use ed25519_dalek::VerifyingKey;
use serde_json::{json, Map, Value};
use thiserror::Error;

use crate::transport::{DocumentTransport, TransportError};

#[derive(Debug, Error)]
pub enum ResolveError {
    #[error("invalid DID {0}")]
    InvalidDid(String),
    #[error("unsupported DID method {0}")]
    UnsupportedMethod(String),
    #[error(transparent)]
    Transport(#[from] TransportError),
    #[error("document for {did} is not a valid DID document: {reason}")]
    InvalidDocument { did: String, reason: String },
    #[error("document fetched for {did} is for {found}")]
    DocumentMismatch { did: String, found: String },
}

#[derive(Clone)]
pub struct Resolver {
    transport: Arc<dyn DocumentTransport>,
}

impl Resolver {
    pub fn new(transport: Arc<dyn DocumentTransport>) -> Self {
        Resolver { transport }
    }

    pub fn resolve(&self, did: &str) -> Result<Document, ResolveError> {
        let method = did
            .strip_prefix("did:")
            .and_then(|rest| rest.split_once(':'))
            .map(|(method, _)| method)
            .ok_or_else(|| ResolveError::InvalidDid(did.to_string()))?;
        match method {
            "key" => resolve_key(did),
            "peer" => resolve_peer(did),
            "web" => self.resolve_web(did),
            other => Err(ResolveError::UnsupportedMethod(other.to_string())),
        }
    }

    fn resolve_web(&self, did: &str) -> Result<Document, ResolveError> {
        let url = did_web_url(did)?;
        let body = self.transport.get(&url)?;
        let document: Document = serde_json::from_slice(&body)
            .map_err(|e| ResolveError::InvalidDocument { did: did.to_string(), reason: e.to_string() })?;
        if document.id.as_str() != did {
            return Err(ResolveError::DocumentMismatch { did: did.to_string(), found: document.id.to_string() });
        }
        Ok(document)
    }
}

/// The `did:key` identifier for an Ed25519 public key.
pub fn did_key_for(key: &VerifyingKey) -> String {
    format!("did:key:{}", affinidi_encoding::encode_multikey(affinidi_encoding::ED25519_PUB, key.as_bytes()))
}

/// The HTTPS URL a `did:web` document is published at: `did.json` under the
/// host's `/.well-known/` directory, with any further segments of the
/// identifier as subdirectories. A port is written percent-encoded in the host
/// segment (`example.com%3A8443`).
pub fn did_web_url(did: &str) -> Result<String, ResolveError> {
    let invalid = || ResolveError::InvalidDid(did.to_string());
    let id = did.strip_prefix("did:web:").ok_or_else(invalid)?;
    let mut segments = id.split(':');
    let host = percent_decode(segments.next().unwrap_or_default()).ok_or_else(invalid)?;
    if host.is_empty() || host.contains('/') {
        return Err(invalid());
    }
    let path: Vec<String> = segments.map(percent_decode).collect::<Option<_>>().ok_or_else(invalid)?;
    if path.iter().any(|s| s.is_empty() || s.contains('/')) {
        return Err(invalid());
    }
    let mut url = format!("https://{host}/.well-known");
    for segment in &path {
        url.push('/');
        url.push_str(segment);
    }
    url.push_str("/did.json");
    Ok(url)
}

fn percent_decode(segment: &str) -> Option<String> {
    let bytes = segment.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' {
            let hex = std::str::from_utf8(bytes.get(i + 1..i + 3)?).ok()?;
            out.push(u8::from_str_radix(hex, 16).ok()?);
            i += 3;
        } else {
            out.push(bytes[i]);
            i += 1;
        }
    }
    String::from_utf8(out).ok()
}

fn resolve_key(did: &str) -> Result<Document, ResolveError> {
    let multibase = did.strip_prefix("did:key:").unwrap_or_default();
    single_key_document(did, multibase)
}

fn resolve_peer(did: &str) -> Result<Document, ResolveError> {
    let id = did.strip_prefix("did:peer:").unwrap_or_default();
    if let Some(multibase) = id.strip_prefix('0') {
        single_key_document(did, multibase)
    } else if let Some(elements) = id.strip_prefix("2.") {
        peer_2_document(did, elements)
    } else {
        Err(ResolveError::InvalidDid(did.to_string()))
    }
}

/// Checks that `multibase` is an Ed25519 multikey.
fn ed25519_multikey(did: &str, multibase: &str) -> Result<(), ResolveError> {
    match affinidi_encoding::decode_multikey_with_codec(multibase) {
        Ok((affinidi_encoding::ED25519_PUB, bytes)) if bytes.len() == 32 => Ok(()),
        _ => Err(ResolveError::InvalidDid(did.to_string())),
    }
}

fn multikey(id: &str, controller: &str, multibase: &str) -> Value {
    json!({ "id": id, "type": "Multikey", "controller": controller, "publicKeyMultibase": multibase })
}

fn single_key_document(did: &str, multibase: &str) -> Result<Document, ResolveError> {
    ed25519_multikey(did, multibase)?;
    let vm_id = format!("{did}#{multibase}");
    to_document(did, json!({
        "@context": ["https://www.w3.org/ns/did/v1", "https://w3id.org/security/multikey/v1"],
        "id": did,
        "verificationMethod": [multikey(&vm_id, did, multibase)],
        "authentication": [vm_id],
        "assertionMethod": [vm_id],
        "capabilityInvocation": [vm_id],
        "capabilityDelegation": [vm_id],
    }))
}

fn peer_2_document(did: &str, elements: &str) -> Result<Document, ResolveError> {
    let invalid = || ResolveError::InvalidDid(did.to_string());
    let mut methods = Vec::new();
    let mut relationships: Map<String, Value> = Map::new();
    let mut services = Vec::new();

    for element in elements.split('.') {
        let mut chars = element.chars();
        let purpose = chars.next().ok_or_else(invalid)?;
        let body = chars.as_str();
        let relationship = match purpose {
            'A' => "assertionMethod",
            'V' => "authentication",
            'E' => "keyAgreement",
            'I' => "capabilityInvocation",
            'D' => "capabilityDelegation",
            'S' => {
                let raw = URL_SAFE_NO_PAD.decode(body.trim_end_matches('=')).map_err(|_| invalid())?;
                let abbreviated: Value = serde_json::from_slice(&raw).map_err(|_| invalid())?;
                let id = match services.len() {
                    0 => format!("{did}#service"),
                    n => format!("{did}#service-{n}"),
                };
                let mut service = expand_service(&abbreviated);
                service["id"] = json!(id);
                services.push(service);
                continue;
            }
            _ => return Err(invalid()),
        };
        if purpose != 'E' {
            ed25519_multikey(did, body)?;
        }
        let vm_id = format!("{did}#key-{}", methods.len() + 1);
        methods.push(multikey(&vm_id, did, body));
        relationships.entry(relationship).or_insert_with(|| json!([])).as_array_mut().unwrap().push(json!(vm_id));
    }

    let mut document = json!({
        "@context": ["https://www.w3.org/ns/did/v1", "https://w3id.org/security/multikey/v1"],
        "id": did,
        "verificationMethod": methods,
        "service": services,
    });
    for (relationship, ids) in relationships {
        document[relationship] = ids;
    }
    to_document(did, document)
}

/// Expands the abbreviated keys peer:2 uses for services (`t`, `s`, `r`, `a`, `dm`).
fn expand_service(value: &Value) -> Value {
    match value {
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(k, v)| {
                    let key = match k.as_str() {
                        "t" => "type",
                        "s" => "serviceEndpoint",
                        "r" => "routingKeys",
                        "a" => "accept",
                        other => other,
                    };
                    (key.to_string(), expand_service(v))
                })
                .collect(),
        ),
        Value::String(s) if s == "dm" => json!("DIDCommMessaging"),
        Value::Array(items) => Value::Array(items.iter().map(expand_service).collect()),
        other => other.clone(),
    }
}

fn to_document(did: &str, value: Value) -> Result<Document, ResolveError> {
    serde_json::from_value(value)
        .map_err(|e| ResolveError::InvalidDocument { did: did.to_string(), reason: e.to_string() })
}
//! Checking the presentations members show at the door.

use std::collections::{BTreeMap, HashSet};
use std::sync::{Arc, Mutex};

use affinidi_did_common::verification_method::VerificationRelationship;
use affinidi_did_common::Document;
use ed25519_dalek::VerifyingKey;
use serde_json::Value;
use thiserror::Error;

use crate::credential::{self, Disclosure, ED25519_SIGNATURE_2020};
use crate::resolver::{ResolveError, Resolver};
use crate::store::Store;

#[derive(Debug, Error)]
pub enum VerifyError {
    #[error("malformed: {0}")]
    Malformed(String),
    #[error("presentation already submitted")]
    Replay,
    #[error("presentation is bound to another nonce")]
    NonceMismatch,
    #[error("presentation is bound to another domain")]
    DomainMismatch,
    #[error("credential subject is not the presenting holder")]
    HolderMismatch,
    #[error(transparent)]
    Resolve(#[from] ResolveError),
    #[error("{0} is not a key its controller signs with")]
    UnknownKey(String),
    #[error("bad signature: {0}")]
    BadSignature(String),
    #[error("credential has expired")]
    Expired,
    #[error("credential is not valid yet")]
    NotYetValid,
    #[error("credential has been revoked")]
    Revoked,
    #[error("no status list {0}")]
    UnknownStatus(String),
    #[error("claim {0} was not issued in this credential")]
    UndisclosedClaim(String),
}

/// A presentation as it arrives from the door scanner.
#[derive(Debug, Clone)]
pub struct Submission {
    /// Set by the scanner's transport for each upload.
    pub request_id: String,
    pub presentation: Value,
}

#[derive(Debug, Clone, PartialEq)]
pub struct VerifiedCredential {
    pub id: String,
    pub issuer: String,
    pub subject: String,
    pub expires_at: i64,
    /// The issuer's `LinkedDomains` endpoint, shown to door staff.
    pub issuer_site: Option<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub struct VerifiedPresentation {
    pub holder: String,
    pub credential: VerifiedCredential,
    /// The claims the holder chose to disclose.
    pub claims: BTreeMap<String, Value>,
}

#[derive(Default)]
struct ReplayGuard {
    seen_nonces: HashSet<String>,
}

impl ReplayGuard {
    fn first_use(&mut self, key: &str) -> bool {
        self.seen_nonces.insert(key.to_string())
    }
}

type Clock = Box<dyn Fn() -> i64 + Send + Sync>;

pub struct Verifier {
    resolver: Resolver,
    store: Arc<Store>,
    clock: Clock,
    replay: Mutex<ReplayGuard>,
}

impl Verifier {
    pub fn new(resolver: Resolver, store: Arc<Store>) -> Self {
        Verifier { resolver, store, clock: Box::new(unix_now), replay: Mutex::default() }
    }

    /// Replaces the wall clock (unix seconds).
    pub fn with_clock(mut self, clock: impl Fn() -> i64 + Send + Sync + 'static) -> Self {
        self.clock = Box::new(clock);
        self
    }

    /// Verifies a presentation against the nonce and domain the scanner issued.
    pub fn verify_presentation(
        &self,
        submission: &Submission,
        expected_nonce: &str,
        expected_domain: &str,
    ) -> Result<VerifiedPresentation, VerifyError> {
        let vp = &submission.presentation;
        if !self.replay.lock().unwrap_or_else(|p| p.into_inner()).first_use(&submission.request_id) {
            return Err(VerifyError::Replay);
        }
        if str_field(vp, "nonce")? != expected_nonce {
            return Err(VerifyError::NonceMismatch);
        }
        if str_field(vp, "domain")? != expected_domain {
            return Err(VerifyError::DomainMismatch);
        }

        let holder = str_field(vp, "holder")?;
        match self.resolver.resolve(holder) {
            Ok(document) => check_proof(vp, &document, &document.authentication)?,
            Err(ResolveError::UnsupportedMethod(_)) => {}
            Err(e) => return Err(e.into()),
        }

        let vc = vp.get("verifiableCredential").ok_or_else(|| malformed("verifiableCredential"))?;
        let credential = self.verify_credential(vc)?;
        if credential.subject != holder {
            return Err(VerifyError::HolderMismatch);
        }

        let committed: HashSet<&str> = vc
            .pointer("/credentialSubject/_sd")
            .and_then(Value::as_array)
            .map(|digests| digests.iter().filter_map(Value::as_str).collect())
            .unwrap_or_default();
        let disclosures: Vec<Disclosure> = match vp.get("disclosures") {
            Some(list) => serde_json::from_value(list.clone()).map_err(|_| malformed("disclosures"))?,
            None => Vec::new(),
        };
        let mut claims = BTreeMap::new();
        for disclosure in disclosures {
            if !committed.contains(disclosure.digest().as_str()) {
                return Err(VerifyError::UndisclosedClaim(disclosure.name));
            }
            claims.insert(disclosure.name, disclosure.value);
        }

        Ok(VerifiedPresentation { holder: holder.to_string(), credential, claims })
    }

    /// Verifies a credential: issuer proof, validity window and status.
    pub fn verify_credential(&self, vc: &Value) -> Result<VerifiedCredential, VerifyError> {
        let issuer = str_field(vc, "issuer")?;
        let subject = vc.pointer("/credentialSubject/id").and_then(Value::as_str).ok_or_else(|| malformed("credentialSubject.id"))?;
        let id = str_field(vc, "id")?;

        let document = self.resolve_issuer(issuer)?;
        check_proof(vc, &document, &document.assertion_method)?;

        let now = (self.clock)();
        let not_before = int_field(vc, "not_before")?;
        let expires_at = int_field(vc, "expires_at")?;
        if now < not_before {
            return Err(VerifyError::NotYetValid);
        }
        if now > expires_at {
            return Err(VerifyError::Expired);
        }

        let list = vc.pointer("/credentialStatus/statusListId").and_then(Value::as_str).ok_or_else(|| malformed("credentialStatus"))?;
        let index = vc.pointer("/credentialStatus/statusListIndex").and_then(Value::as_u64).ok_or_else(|| malformed("credentialStatus"))?;
        match self.store.is_revoked(list, index as usize) {
            Some(false) => {}
            Some(true) => return Err(VerifyError::Revoked),
            None => return Err(VerifyError::UnknownStatus(list.to_string())),
        }

        let issuer_site = document
            .service
            .iter()
            .find(|service| service.type_.iter().any(|t| t == "LinkedDomains"))
            .and_then(|service| service.service_endpoint.get_uri());

        Ok(VerifiedCredential {
            id: id.to_string(),
            issuer: issuer.to_string(),
            subject: subject.to_string(),
            expires_at,
            issuer_site,
        })
    }

    /// The DID document an issuer's credentials are checked against.
    pub fn resolve_issuer(&self, did: &str) -> Result<Document, VerifyError> {
        if let Some(issuer) = self.store.onboarded_issuer(did) {
            return Ok(issuer.document);
        }
        Ok(self.resolver.resolve(did)?)
    }
}

/// Checks `document`'s proof against a key `signer` lists under `relationship`.
fn check_proof(document: &Value, signer: &Document, relationship: &[VerificationRelationship]) -> Result<(), VerifyError> {
    let proof = document.get("proof").ok_or_else(|| malformed("proof"))?;
    if proof.get("type").and_then(Value::as_str) == Some(ED25519_SIGNATURE_2020) {
        let method = proof.get("verificationMethod").and_then(Value::as_str).ok_or_else(|| malformed("proof.verificationMethod"))?;
        let key = listed_key(signer, relationship, method)?;
        credential::verify_signature(document, &key).map_err(VerifyError::BadSignature)?;
    }
    Ok(())
}

fn listed_key(signer: &Document, relationship: &[VerificationRelationship], method: &str) -> Result<VerifyingKey, VerifyError> {
    let unknown = || VerifyError::UnknownKey(method.to_string());
    let absolute = |reference: &str| match reference.strip_prefix('#') {
        Some(fragment) => format!("{}#{fragment}", signer.id),
        None => reference.to_string(),
    };
    let listed = relationship.iter().find_map(|entry| match entry {
        VerificationRelationship::Reference(reference) if absolute(reference) == method => {
            signer.verification_method.iter().find(|vm| absolute(vm.id.as_str()) == method).cloned()
        }
        VerificationRelationship::VerificationMethod(vm) if absolute(vm.id.as_str()) == method => Some((**vm).clone()),
        _ => None,
    });
    let vm = listed.ok_or_else(unknown)?;
    match vm.decode_public_key() {
        Ok((affinidi_encoding::ED25519_PUB, bytes)) => {
            let bytes: [u8; 32] = bytes.try_into().map_err(|_| unknown())?;
            VerifyingKey::from_bytes(&bytes).map_err(|_| unknown())
        }
        _ => Err(unknown()),
    }
}

fn malformed(field: &str) -> VerifyError {
    VerifyError::Malformed(format!("missing or invalid {field}"))
}

fn str_field<'a>(value: &'a Value, field: &str) -> Result<&'a str, VerifyError> {
    value.get(field).and_then(Value::as_str).ok_or_else(|| malformed(field))
}

fn int_field(value: &Value, field: &str) -> Result<i64, VerifyError> {
    value.get(field).and_then(Value::as_i64).ok_or_else(|| malformed(field))
}

fn unix_now() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or_default()
}
//! Onboarding issuers and issuing credentials on their behalf.

use ed25519_dalek::{SigningKey, VerifyingKey};
use serde_json::{json, Value};
use thiserror::Error;

use crate::credential::{self, Disclosure, CREDENTIALS_CONTEXT};
use crate::resolver::{ResolveError, Resolver};
use crate::store::{CredentialRecord, OnboardedIssuer, Store};

#[derive(Debug, Error)]
pub enum OnboardError {
    #[error(transparent)]
    Resolve(#[from] ResolveError),
    #[error("{0} publishes no assertion key")]
    NoAssertionKey(String),
}

/// Approves an issuer: resolves its DID and records it with its document.
pub fn onboard(
    resolver: &Resolver,
    store: &Store,
    did: &str,
    name: &str,
    onboarded_at: &str,
) -> Result<OnboardedIssuer, OnboardError> {
    let document = resolver.resolve(did)?;
    if document.assertion_method.is_empty() {
        return Err(OnboardError::NoAssertionKey(did.to_string()));
    }
    let record = OnboardedIssuer {
        did: did.to_string(),
        name: name.to_string(),
        onboarded_at: onboarded_at.to_string(),
        document,
    };
    store.record_onboarded_issuer(record.clone());
    Ok(record)
}

#[derive(Debug, Error, PartialEq, Eq)]
pub enum IssueError {
    #[error("holder {0} is not a did:key")]
    InvalidHolder(String),
    #[error("credential would expire before it becomes valid")]
    InvalidValidity,
    #[error("status list {0} is full")]
    StatusListFull(String),
}

/// What a member asked for.
#[derive(Debug, Clone)]
pub struct CredentialRequest {
    /// The holder's `did:key`.
    pub holder: String,
    /// Added to `type` after `VerifiableCredential`.
    pub credential_type: String,
    pub claims: Vec<(String, Value)>,
    /// Unix seconds.
    pub issued_at: i64,
    /// Unix seconds; defaults to `issued_at`.
    pub not_before: Option<i64>,
    /// Unix seconds.
    pub expires_at: i64,
}

/// A signed credential plus the disclosures only its holder receives.
#[derive(Debug, Clone)]
pub struct IssuedCredential {
    pub credential: Value,
    pub disclosures: Vec<Disclosure>,
}

/// An onboarded issuer's signing identity.
pub struct Issuer {
    did: String,
    verification_method: String,
    key: SigningKey,
}

impl Issuer {
    /// `verification_method` is the DID URL of the key in the issuer's document.
    pub fn new(did: &str, verification_method: &str, seed: &[u8; 32]) -> Self {
        Issuer {
            did: did.to_string(),
            verification_method: verification_method.to_string(),
            key: SigningKey::from_bytes(seed),
        }
    }

    pub fn did(&self) -> &str {
        &self.did
    }

    pub fn verifying_key(&self) -> VerifyingKey {
        self.key.verifying_key()
    }

    /// The status list this issuer's credentials are indexed into.
    pub fn status_list(&self) -> String {
        format!("{}#revocation", self.did)
    }

    pub fn issue(&self, store: &Store, request: &CredentialRequest) -> Result<IssuedCredential, IssueError> {
        let holder_key = request.holder.strip_prefix("did:key:").unwrap_or_default();
        match affinidi_encoding::decode_multikey_with_codec(holder_key) {
            Ok((affinidi_encoding::ED25519_PUB, _)) => {}
            _ => return Err(IssueError::InvalidHolder(request.holder.clone())),
        }
        let not_before = request.not_before.unwrap_or(request.issued_at);
        if request.expires_at < not_before {
            return Err(IssueError::InvalidValidity);
        }

        let disclosures: Vec<Disclosure> =
            request.claims.iter().map(|(name, value)| Disclosure::new(name, value.clone())).collect();
        let mut digests: Vec<String> = disclosures.iter().map(Disclosure::digest).collect();
        digests.sort();

        let status_list = self.status_list();
        let status_index =
            store.allocate_status_index(&status_list).ok_or_else(|| IssueError::StatusListFull(status_list.clone()))?;

        let id = credential::random_urn();
        let mut vc = json!({
            "@context": [CREDENTIALS_CONTEXT],
            "id": id,
            "type": ["VerifiableCredential", request.credential_type],
            "issuer": self.did,
            "issued_at": request.issued_at,
            "not_before": not_before,
            "expires_at": request.expires_at,
            "credentialSubject": { "id": request.holder, "_sd": digests },
            "credentialStatus": {
                "type": "StatusListEntry",
                "statusListId": status_list,
                "statusListIndex": status_index,
            },
        });
        credential::sign(&mut vc, &self.key, &self.verification_method, "assertionMethod", request.issued_at);

        store.record_credential(CredentialRecord {
            id,
            issuer: self.did.clone(),
            subject: request.holder.clone(),
            status_list,
            status_index,
            expires_at: request.expires_at,
        });
        Ok(IssuedCredential { credential: vc, disclosures })
    }
}

