//! Fetching hosted DID documents.
//!
//! Issuer `did.json` documents are published to the document bucket behind
//! the issuers' domains (see `reference/infra/hosted-dids/`). The service
//! reads them through a [`DocumentTransport`], so the same resolver runs
//! against the bucket mirror in development and against fixtures in tests.

use std::collections::HashMap;
use std::path::{Component, Path, PathBuf};

use thiserror::Error;
use url::Url;

#[derive(Debug, Error, PartialEq, Eq)]
pub enum TransportError {
    #[error("invalid document URL {0}")]
    InvalidUrl(String),
    #[error("no document at {0}")]
    NotFound(String),
    #[error("reading {url}: {reason}")]
    Io { url: String, reason: String },
}

/// Something that can GET a document by its HTTPS URL.
pub trait DocumentTransport: Send + Sync {
    fn get(&self, url: &str) -> Result<Vec<u8>, TransportError>;
}

/// Serves `https://<authority>/<path>` from `<root>/<authority>/<path>`: a
/// local mirror of the document bucket, laid out the way the bucket keys
/// its objects.
#[derive(Debug, Clone)]
pub struct MirrorTransport {
    root: PathBuf,
}

impl MirrorTransport {
    pub fn new(root: impl AsRef<Path>) -> Self {
        MirrorTransport { root: root.as_ref().to_path_buf() }
    }

    /// The mirror at `$DID_MIRROR_ROOT`, or the checked-in copy of the bucket.
    pub fn from_env() -> Self {
        match std::env::var_os("DID_MIRROR_ROOT") {
            Some(root) => MirrorTransport::new(root),
            None => MirrorTransport::new(Path::new(env!("CARGO_MANIFEST_DIR")).join("../reference/infra/hosted-dids")),
        }
    }

    fn path_for(&self, url: &str) -> Result<PathBuf, TransportError> {
        let invalid = || TransportError::InvalidUrl(url.to_string());
        let parsed = Url::parse(url).map_err(|_| invalid())?;
        if parsed.scheme() != "https" || url.contains("/../") {
            return Err(invalid());
        }
        let host = parsed.host_str().ok_or_else(invalid)?;
        let authority = match parsed.port() {
            Some(port) => format!("{host}:{port}"),
            None => host.to_string(),
        };
        let mut path = self.root.join(authority);
        for segment in parsed.path_segments().into_iter().flatten() {
            let segment = Path::new(segment);
            if segment.components().any(|c| !matches!(c, Component::Normal(_))) {
                return Err(invalid());
            }
            path.push(segment);
        }
        Ok(path)
    }
}

impl DocumentTransport for MirrorTransport {
    fn get(&self, url: &str) -> Result<Vec<u8>, TransportError> {
        let path = self.path_for(url)?;
        std::fs::read(&path).map_err(|e| match e.kind() {
            std::io::ErrorKind::NotFound => TransportError::NotFound(url.to_string()),
            _ => TransportError::Io { url: url.to_string(), reason: e.to_string() },
        })
    }
}

/// An in-memory set of documents keyed by URL.
#[derive(Debug, Clone, Default)]
pub struct StaticTransport {
    documents: HashMap<String, Vec<u8>>,
}

impl StaticTransport {
    pub fn with(mut self, url: &str, body: impl Into<Vec<u8>>) -> Self {
        self.documents.insert(url.to_string(), body.into());
        self
    }
}

impl DocumentTransport for StaticTransport {
    fn get(&self, url: &str) -> Result<Vec<u8>, TransportError> {
        self.documents.get(url).cloned().ok_or_else(|| TransportError::NotFound(url.to_string()))
    }
}
//! In-memory state: onboarded issuers, issued credentials and status lists.

use std::collections::HashMap;
use std::sync::Mutex;

use affinidi_did_common::Document;
use serde::{Deserialize, Serialize};

use crate::status::{StatusList, DEFAULT_CAPACITY};

const ONBOARDING_DATA: &str = include_str!("../data/onboarded-issuers.json");

/// An issuer approved to issue through the service.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct OnboardedIssuer {
    pub did: String,
    pub name: String,
    pub onboarded_at: String,
    pub document: Document,
}

/// What the service remembers about a credential it issued.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct CredentialRecord {
    pub id: String,
    pub issuer: String,
    pub subject: String,
    pub status_list: String,
    pub status_index: usize,
    pub expires_at: i64,
}

#[derive(Default)]
struct Inner {
    issuers: HashMap<String, OnboardedIssuer>,
    credentials: HashMap<String, CredentialRecord>,
    status_lists: HashMap<String, StatusList>,
}

#[derive(Default)]
pub struct Store {
    inner: Mutex<Inner>,
}

impl Store {
    pub fn new() -> Self {
        Store::default()
    }

    /// A store holding every issuer in `data/onboarded-issuers.json`.
    pub fn from_onboarding_data() -> Result<Self, serde_json::Error> {
        let issuers: Vec<OnboardedIssuer> = serde_json::from_str(ONBOARDING_DATA)?;
        let store = Store::new();
        for issuer in issuers {
            store.record_onboarded_issuer(issuer);
        }
        Ok(store)
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, Inner> {
        self.inner.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
    }

    pub fn record_onboarded_issuer(&self, issuer: OnboardedIssuer) {
        self.lock().issuers.insert(issuer.did.clone(), issuer);
    }

    /// Issuer documents are self-contained, as with the peer DIDs issuers
    /// first onboarded with: keys and service endpoints travel with the
    /// document, so the copy recorded at onboarding is all verification needs.
    pub fn onboarded_issuer(&self, did: &str) -> Option<OnboardedIssuer> {
        self.lock().issuers.get(did).cloned()
    }

    pub fn onboarded_issuers(&self) -> Vec<OnboardedIssuer> {
        let mut issuers: Vec<_> = self.lock().issuers.values().cloned().collect();
        issuers.sort_by(|a, b| a.did.cmp(&b.did));
        issuers
    }

    pub fn record_credential(&self, record: CredentialRecord) {
        self.lock().credentials.insert(record.id.clone(), record);
    }

    pub fn credential(&self, id: &str) -> Option<CredentialRecord> {
        self.lock().credentials.get(id).cloned()
    }

    /// Reserves an index in `list`, creating the list on first use.
    pub fn allocate_status_index(&self, list: &str) -> Option<usize> {
        self.lock()
            .status_lists
            .entry(list.to_string())
            .or_insert_with(|| StatusList::new(DEFAULT_CAPACITY))
            .allocate()
    }

    /// Sets the bit at `index` in `list`; `false` if there is no such list.
    pub fn set_status(&self, list: &str, index: usize, revoked: bool) -> bool {
        match self.lock().status_lists.get_mut(list) {
            Some(status) => {
                status.set(index, revoked);
                true
            }
            None => false,
        }
    }

    pub fn is_revoked(&self, list: &str, index: usize) -> Option<bool> {
        self.lock().status_lists.get(list).map(|status| status.is_set(index))
    }

    /// The published form of `list`.
    pub fn encoded_status_list(&self, list: &str) -> Option<String> {
        self.lock().status_lists.get(list).map(StatusList::encode)
    }
}
//! The credential wire format: canonical JSON, Ed25519 proofs and
//! selectively disclosable claims.
//!
//! Every signature in the system covers the RFC 8785 (JCS) form of a document
//! with its `proof` member removed, so a document signed by the wallet and
//! verified here (or the other way round) hashes the same bytes on both sides.

use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use base64::Engine;
use ed25519_dalek::{Signature, Signer, SigningKey, Verifier as _, VerifyingKey};
use serde::{Deserialize, Serialize};
use serde_json::{json, Value};
use sha2::{Digest, Sha256};

pub const ED25519_SIGNATURE_2020: &str = "Ed25519Signature2020";
pub const CREDENTIALS_CONTEXT: &str = "https://www.w3.org/2018/credentials/v1";

/// One selectively disclosable claim, as handed to the holder at issuance.
///
/// The credential itself only carries [`Disclosure::digest`] in
/// `credentialSubject._sd`; the holder reveals a claim by presenting its
/// disclosure next to the credential.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct Disclosure {
    pub salt: String,
    pub name: String,
    pub value: Value,
}

impl Disclosure {
    pub fn new(name: &str, value: Value) -> Self {
        Disclosure { salt: random_token(16), name: name.to_string(), value }
    }

    /// base64url (no padding) of SHA-256 over the canonical `[salt, name, value]` array.
    pub fn digest(&self) -> String {
        let triple = json!([self.salt, self.name, self.value]);
        URL_SAFE_NO_PAD.encode(Sha256::digest(canonicalize(&triple).as_bytes()))
    }
}

/// The bytes a proof signs: the canonical form of `document` without `proof`.
pub fn signing_input(document: &Value) -> Vec<u8> {
    match document {
        Value::Object(map) if map.contains_key("proof") => {
            let mut unsigned = map.clone();
            unsigned.remove("proof");
            canonicalize(&Value::Object(unsigned)).into_bytes()
        }
        other => canonicalize(other).into_bytes(),
    }
}

/// Adds (or replaces) an `Ed25519Signature2020` proof on `document`.
pub fn sign(document: &mut Value, key: &SigningKey, verification_method: &str, purpose: &str, created: i64) {
    let signature = key.sign(&signing_input(document));
    document["proof"] = json!({
        "type": ED25519_SIGNATURE_2020,
        "created": created,
        "verificationMethod": verification_method,
        "proofPurpose": purpose,
        "proofValue": affinidi_encoding::encode_base58btc(&signature.to_bytes()),
    });
}

/// Checks the `proofValue` of `document` against `key`.
pub fn verify_signature(document: &Value, key: &VerifyingKey) -> Result<(), String> {
    let proof_value = document
        .pointer("/proof/proofValue")
        .and_then(Value::as_str)
        .ok_or("proof has no proofValue")?;
    let bytes = affinidi_encoding::decode_base58btc(proof_value).map_err(|e| format!("proofValue: {e}"))?;
    let signature = Signature::from_slice(&bytes).map_err(|e| format!("proofValue: {e}"))?;
    key.verify(&signing_input(document), &signature).map_err(|_| "signature does not match".to_string())
}

/// RFC 8785 JSON Canonicalization Scheme.
///
/// Object members are ordered by the UTF-16 code units of their names,
/// strings use the minimal JSON escaping, and numbers are written the way
/// ECMAScript prints them (integral values without a fraction).
pub fn canonicalize(value: &Value) -> String {
    let mut out = String::new();
    write_canonical(value, &mut out);
    out
}

fn write_canonical(value: &Value, out: &mut String) {
    match value {
        Value::Null | Value::Bool(_) | Value::String(_) => {
            out.push_str(&serde_json::to_string(value).expect("scalars serialize"))
        }
        Value::Number(n) => out.push_str(&canonical_number(n)),
        Value::Array(items) => {
            out.push('[');
            for (i, item) in items.iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                write_canonical(item, out);
            }
            out.push(']');
        }
        Value::Object(map) => {
            let mut entries: Vec<(&String, &Value)> = map.iter().collect();
            entries.sort_by(|(a, _), (b, _)| a.encode_utf16().cmp(b.encode_utf16()));
            out.push('{');
            for (i, (key, item)) in entries.into_iter().enumerate() {
                if i > 0 {
                    out.push(',');
                }
                out.push_str(&serde_json::to_string(key).expect("keys serialize"));
                out.push(':');
                write_canonical(item, out);
            }
            out.push('}');
        }
    }
}

fn canonical_number(n: &serde_json::Number) -> String {
    if n.is_i64() || n.is_u64() {
        return n.to_string();
    }
    let f = n.as_f64().unwrap_or(0.0);
    if f == f.trunc() && f.abs() < 1e21 {
        format!("{}", f as i128)
    } else {
        format!("{f}")
    }
}

/// A random base64url token of `bytes` bytes of entropy.
pub fn random_token(bytes: usize) -> String {
    let mut buf = vec![0u8; bytes];
    getrandom::fill(&mut buf).expect("system randomness");
    URL_SAFE_NO_PAD.encode(buf)
}

/// A random (version 4) `urn:uuid:` identifier.
pub fn random_urn() -> String {
    let mut b = [0u8; 16];
    getrandom::fill(&mut b).expect("system randomness");
    b[6] = (b[6] & 0x0f) | 0x40;
    b[8] = (b[8] & 0x3f) | 0x80;
    let hex: String = b.iter().map(|x| format!("{x:02x}")).collect();
    format!("urn:uuid:{}-{}-{}-{}-{}", &hex[0..8], &hex[8..12], &hex[12..16], &hex[16..20], &hex[20..32])
}
//! Revocation through status lists.
//!
//! Each issuer publishes one bitstring. Every credential it issues carries an
//! index into that bitstring (`credentialStatus.statusListIndex`); the
//! credential is revoked when the bit at that index is 1. Bit 0 is the
//! most significant bit of the first byte.

use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use base64::Engine;
use thiserror::Error;

use crate::store::Store;

/// Bits per list: large enough that an index says little about when a
/// credential was issued.
pub const DEFAULT_CAPACITY: usize = 131_072;

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StatusList {
    bits: Vec<u8>,
    capacity: usize,
    allocated: usize,
}

impl StatusList {
    pub fn new(capacity: usize) -> Self {
        StatusList { bits: vec![0; capacity.div_ceil(8)], capacity, allocated: 0 }
    }

    pub fn capacity(&self) -> usize {
        self.capacity
    }

    /// Reserves the next unused index, or `None` once the list is full.
    pub fn allocate(&mut self) -> Option<usize> {
        if self.allocated >= self.capacity {
            return None;
        }
        self.allocated += 1;
        Some(self.allocated)
    }

    pub fn set(&mut self, index: usize, revoked: bool) {
        let mask = 0x80u8 >> (index % 8);
        if let Some(byte) = self.bits.get_mut(index / 8) {
            if revoked {
                *byte |= mask;
            } else {
                *byte &= !mask;
            }
        }
    }

    pub fn is_set(&self, index: usize) -> bool {
        let mask = 0x80u8 >> (index % 8);
        self.bits.get(index / 8).is_some_and(|byte| byte & mask != 0)
    }

    /// The published form of the list: base64url of the bitstring.
    pub fn encode(&self) -> String {
        URL_SAFE_NO_PAD.encode(&self.bits)
    }

    pub fn decode(encoded: &str, capacity: usize) -> Option<Self> {
        let bits = URL_SAFE_NO_PAD.decode(encoded).ok()?;
        (bits.len() == capacity.div_ceil(8)).then_some(StatusList { bits, capacity, allocated: capacity })
    }
}

#[derive(Debug, Error, PartialEq, Eq)]
pub enum StatusError {
    #[error("no credential {0}")]
    UnknownCredential(String),
    #[error("no status list {0}")]
    UnknownList(String),
}

/// What changed when a credential's status flipped.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct StatusChange {
    pub credential_id: String,
    pub issuer: String,
    pub status_list: String,
    pub status_index: usize,
    pub revoked: bool,
}

/// Revokes an issued credential by setting its bit in its issuer's list.
pub fn revoke_credential(store: &Store, credential_id: &str) -> Result<StatusChange, StatusError> {
    let record = store
        .credential(credential_id)
        .ok_or_else(|| StatusError::UnknownCredential(credential_id.to_string()))?;
    if !store.set_status(&record.status_list, record.status_index, true) {
        return Err(StatusError::UnknownList(record.status_list));
    }
    Ok(StatusChange {
        credential_id: record.id,
        issuer: record.issuer,
        status_list: record.status_list,
        status_index: record.status_index,
        revoked: true,
    })
}

