/// The DID document an issuer's credentials are checked against.
pub fn resolve_issuer(&self, did: &str) -> Result<Document, VerifyError> {
    if let Some(issuer) = self.store.onboarded_issuer(did) {
        return Ok(issuer.document);
    }
    Ok(self.resolver.resolve(did)?)
}

input.new_string:
/// The DID document an issuer's credentials are checked against: the one
/// the issuer publishes now. The copy recorded at onboarding is not used —
/// a `did:web` issuer rotates keys and moves endpoints by republishing its
/// document, and only the current document is authoritative.
pub fn resolve_issuer(&self, did: &str) -> Result<Document, VerifyError> {
