new='''    /// Sends `change` to the platform subscribers and to every subscriber of
    /// the issuing tenant.
    ///
    /// Subscriptions are read through the `tenant-kind` index, so the lookup
    /// costs the same however many other settings the tenant has. Deliveries
    /// run concurrently and each attempt is bounded by [`ATTEMPT_TIMEOUT`], so
    /// a slow or hanging endpoint delays only its own delivery.
    pub async fn notify(&self, change: &StatusChange) {
        let tenant = change.issuer.as_str();
        let body = payload(change);
        let deadline = Instant::now() + DISPATCH_BUDGET;

        let fan_out = async {
            let mut targets = self.platform.clone();
            targets.extend(self.subscriptions(tenant).await);
            let deliveries = targets.iter().map(|sub| async move { (sub, self.deliver(tenant, sub, &body, deadline).await) });
            join_all(deliveries.collect()).await.into_iter().any(|(sub, delivered)| sub.id == CANARY_ID && delivered)
        };

        match tokio::time::timeout_at(deadline, fan_out).await {
            Ok(canary_delivered) => self.canary_ok.store(canary_delivered, Ordering::SeqCst),
            Err(_) => {
                // Some subscribers were not told: the notifier is not healthy,
                // whatever the canary said.
                self.canary_ok.store(false, Ordering::SeqCst);
                eprintln!("notifier: {tenant}: fan-out for {} did not finish within {DISPATCH_BUDGET:?}", change.credential_id);
            }
        }
    }

    /// The tenant's webhook subscriptions.
    async fn subscriptions(&self, tenant: &str) -> Vec<Subscription> {
        self.settings.query_kind(tenant, WEBHOOK_KIND).await.iter().filter_map(Subscription::from_setting).collect()
    }

    /// Delivers `body` to `sub`, retrying calls that got no answer while
    /// there is time left before `deadline`; `true` if delivered.
    async fn deliver(&self, tenant: &str, sub: &Subscription, body: &[u8], deadline: Instant) -> bool {
        for attempt in 1..=MAX_ATTEMPTS {
            match self.dispatch(tenant, sub, body).await {
                Attempt::Delivered => return true,
                Attempt::Refused => return false,
                Attempt::NoAnswer => {}
            }
            let backoff = RETRY_BACKOFF * attempt;
            if attempt == MAX_ATTEMPTS || Instant::now() + backoff + ATTEMPT_TIMEOUT > deadline {
                break;
            }
            tokio::time::sleep(backoff).await;
        }
        false
    }

